package com.aistock.market.alert;
import static com.aistock.market.alert.AlertEvidenceRecords.*;
import com.aistock.market.calendar.*;import com.aistock.market.support.MarketDatabaseFixture;
import com.aistock.market.ingestion.*;import com.aistock.market.version.MarketVersionRepository;
import com.aistock.market.forecast.ForecastCandidate;import com.aistock.market.quotation.*;
import com.aistock.common.BusinessException;import java.time.*;import java.util.*;
import org.junit.jupiter.api.*;import static org.junit.jupiter.api.Assertions.*;
@Tag("mysql") class AlertEvidenceMysqlTest {
 final Clock now=Clock.fixed(AlertEvidenceValidatorTest.NOW,ZoneOffset.UTC);
 final MarketDatabaseFixture f=new MarketDatabaseFixture();final MarketVersionRepository market=new MarketVersionRepository(f.jdbc());
 final CalendarService calendar=new CalendarService(f.jdbc(),r->{var days=new ArrayList<CalendarRecords.Day>();for(var d=r.start();!d.isAfter(r.end());d=d.plusDays(1))days.add(new CalendarRecords.Day(d,d.getDayOfWeek().getValue()<6));return new CalendarRecords.Candidate("baostock",r.start(),r.end(),now.instant(),CalendarService.hash(days),days);},now,7);
 UUID raw(List<RawBar> bars){return UUID.fromString(new PublicationService(market,new CandidateValidator()).publish(new MarketCandidate(UUID.randomUUID().toString(),"SH600030","SH600030","fixture",true,"ACTIVE","baostock","RAW",now.instant(),null,"a".repeat(64),bars,List.of(),0L)).versionId());}
 List<RawBar> bars(){return List.of(AlertEvidenceValidatorTest.bar(LocalDate.of(2026,10,8),"100",1),AlertEvidenceValidatorTest.bar(LocalDate.of(2026,10,9),"50",1));}
 void setupCalendar(){calendar.refresh(new CalendarRecords.Request("fixture-calendar",LocalDate.of(2026,10,1),LocalDate.of(2026,10,14)));}
 Request request(UUID raw){return new Request(UUID.randomUUID(),"SH600030",raw,LocalDate.of(2026,10,9),now.instant().plusSeconds(90));}
 Source candidate(Request r){return new Source("AVAILABLE",new ForecastCandidate(r.operationId().toString(),r.instrumentId(),r.rawVersionId().toString(),"baostock","baostock-backward-close-over-raw-v1",now.instant(),"b".repeat(64),bars().stream().map(b->new ForecastCandidate.PairedBar(b,new java.math.BigDecimal("100"))).toList(),AlertEvidenceValidatorTest.days().subList(0,2)),null);}
 AlertEvidenceService service(AlertEvidenceCollector collector){return new AlertEvidenceService(market,calendar,collector,now,20);}
 @Test void savesImmutableEvidenceAndReplaysWithoutSource(){var raw=raw(bars());setupCalendar();var calls=new java.util.concurrent.atomic.AtomicInteger();var s=service((r,p)->{calls.incrementAndGet();return candidate(r);});var r=request(raw);var result=s.prepare(r);assertEquals("AVAILABLE",result.state());assertEquals(result,s.prepare(r));assertEquals(result,s.operation(r.operationId()));assertEquals(1,calls.get());var evidence=s.version(result.evidenceId());assertEquals("VERIFIED",evidence.priceState());assertEquals("50",evidence.rawClose());assertEquals("VERIFIED",evidence.changeState());assertEquals("100",evidence.previousBackwardClose());assertEquals("100",evidence.currentBackwardClose());assertEquals(raw,evidence.rawVersionId());assertEquals(raw.toString(),f.jdbc().queryForObject("select version_id from instrument_data_head",String.class));}
 @Test void changedSameOperationConflicts(){var raw=raw(bars());setupCalendar();var s=service((r,p)->candidate(r));var r=request(raw);s.prepare(r);assertEquals("ALERT_EVIDENCE_OPERATION_CONFLICT",assertThrows(BusinessException.class,()->s.prepare(new Request(r.operationId(),r.instrumentId(),r.rawVersionId(),r.tradeDate().minusDays(1),r.leaseUntil()))).code());}
 @Test void failedOrInvalidComparableSourceDoesNotBlockVerifiedPrice(){var raw=raw(bars());setupCalendar();for(var state:List.of("SOURCE_TIMEOUT","SOURCE_INVALID")){var s=service((r,p)->new Source(state,null,state));var result=s.prepare(request(raw));assertEquals("AVAILABLE",result.state());var evidence=s.version(result.evidenceId());assertEquals("VERIFIED",evidence.priceState());assertEquals("50",evidence.rawClose());assertNotEquals("VERIFIED",evidence.changeState());assertNull(evidence.previousBackwardClose());assertNull(evidence.currentBackwardClose());}}
 @Test void missingImmediatePreviousRawDoesNotCollectOrInventZero(){var raw=raw(List.of(bars().get(1)));setupCalendar();var s=service((r,p)->{throw new AssertionError("no collect without previous day");});var e=s.version(s.prepare(request(raw)).evidenceId());assertEquals("VERIFIED",e.priceState());assertEquals("MISSING_PREVIOUS_RAW",e.changeState());assertNull(e.previousBackwardClose());}
 @Test void staleRequestAndUnknownCalendarDoNotCreateUsableEvidence(){var raw=raw(bars());var s=service((r,p)->{throw new AssertionError("no source");});assertEquals("FAILED",s.prepare(request(raw)).state());setupCalendar();var r=request(raw);assertEquals("SKIPPED_STALE",s.prepare(new Request(r.operationId(),r.instrumentId(),raw,r.tradeDate().minusDays(1),r.leaseUntil())).state());assertEquals(0,f.jdbc().queryForObject("select count(*) from alert_evidence_version",Integer.class));}
 @Test void expiredLeaseAndUnknownReceiptAreExplicit(){var raw=raw(bars());setupCalendar();var s=service((r,p)->candidate(r));var r=request(raw);assertEquals("ATTEMPT_EXPIRED",s.prepare(new Request(r.operationId(),r.instrumentId(),raw,r.tradeDate(),now.instant().minusSeconds(1))).errorCode());assertEquals("RESOURCE_NOT_FOUND",assertThrows(BusinessException.class,()->s.operation(UUID.randomUUID())).code());assertEquals(0,f.jdbc().queryForObject("select count(*) from alert_evidence_version",Integer.class));}
 @Test void duplicateConcurrentOperationHasOneFinalEvidence()throws Exception{var raw=raw(bars());setupCalendar();var entered=new java.util.concurrent.CountDownLatch(1);var release=new java.util.concurrent.CountDownLatch(1);var s=service((r,p)->{entered.countDown();try{if(!release.await(5,java.util.concurrent.TimeUnit.SECONDS))throw new IllegalStateException();}catch(InterruptedException e){Thread.currentThread().interrupt();throw new IllegalStateException(e);}return candidate(r);});var r=request(raw);var pool=java.util.concurrent.Executors.newSingleThreadExecutor();try{var first=pool.submit(()->s.prepare(r));assertTrue(entered.await(5,java.util.concurrent.TimeUnit.SECONDS));assertEquals("RUNNING",s.prepare(r).state());release.countDown();var done=first.get(5,java.util.concurrent.TimeUnit.SECONDS);assertEquals("AVAILABLE",done.state());assertEquals(done,s.operation(r.operationId()));assertEquals(1,f.jdbc().queryForObject("select count(*) from alert_evidence_version",Integer.class));}finally{release.countDown();pool.shutdownNow();}}

 @Test void missingLatestDayNeverYieldsPriceOrChange(){setupCalendar();var raw=raw(List.of(bars().get(0)));var s=service((r,p)->{throw new AssertionError("no source for missing current price");});var e=s.version(s.prepare(request(raw)).evidenceId());assertEquals("MISSING",e.priceState());assertNull(e.rawClose());assertEquals("MISSING_CURRENT_RAW",e.changeState());}
 @Test void expiredRunningOperationCannotPublishLateSource(){var raw=raw(bars());setupCalendar();var offset=new java.util.concurrent.atomic.AtomicLong();Clock changing=new Clock(){public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId z){return this;}public Instant instant(){return now.instant().plusSeconds(offset.get());}};var s=new AlertEvidenceService(market,calendar,(r,p)->{offset.set(91);return candidate(r);},changing,20);var receipt=s.prepare(request(raw));assertEquals("FAILED",receipt.state());assertEquals("ATTEMPT_EXPIRED",receipt.errorCode());assertEquals(0,f.jdbc().queryForObject("select count(*) from alert_evidence_version",Integer.class));}
 @Test void futureDateCannotCreateOperation(){var raw=raw(bars());setupCalendar();var s=service((r,p)->candidate(r));var r=request(raw);assertEquals("ALERT_EVIDENCE_REQUEST_INVALID",assertThrows(BusinessException.class,()->s.prepare(new Request(r.operationId(),r.instrumentId(),raw,LocalDate.of(2026,10,12),r.leaseUntil()))).code());assertEquals(0,f.jdbc().queryForObject("select count(*) from alert_evidence_operation",Integer.class));}

 @Test void suspendedLatestDayCannotProducePriceOrComparableChange(){var previous=bars().get(0);var current=AlertEvidenceValidatorTest.bar(LocalDate.of(2026,10,9),"50",0);var raw=raw(List.of(previous,current));setupCalendar();var s=service((r,p)->{throw new AssertionError("no collection during suspension");});var e=s.version(s.prepare(request(raw)).evidenceId());assertEquals("SUSPENDED",e.priceState());assertEquals("SUSPENDED",e.changeState());assertNull(e.rawClose());assertNull(e.currentBackwardClose());}

 @Test void narrowIndependentCalendarFallsBackToCompleteFixedRawCalendar(){var raw=UUID.fromString(new PublicationService(market,new CandidateValidator()).publish(new MarketCandidate(UUID.randomUUID().toString(),"SH600030","SH600030","fixture",true,"ACTIVE","baostock","RAW",now.instant(),null,"a".repeat(64),bars(),AlertEvidenceValidatorTest.days().subList(0,2),0L)).versionId());calendar.refresh(new CalendarRecords.Request("narrow",LocalDate.of(2026,10,9),LocalDate.of(2026,10,14)));var s=service((r,p)->candidate(r));var e=s.version(s.prepare(request(raw)).evidenceId());assertEquals("VERIFIED",e.changeState());assertEquals(LocalDate.of(2026,10,8),e.previousTradeDate());assertNull(e.calendarVersionId());}
 @Test void referenceMetadataUsesStoredRawIdentityWithoutReadingOrRecomputingEvidence(){var raw=raw(bars());setupCalendar();var s=service((r,p)->candidate(r));var id=s.prepare(request(raw)).evidenceId();var control=new AlertEvidenceReferenceController(f.jdbc());var result=new com.fasterxml.jackson.databind.ObjectMapper().valueToTree(control.reference(id,null).data());assertEquals(3,result.size());assertEquals(raw.toString(),result.path("rawVersionId").asText());assertEquals(id.toString(),result.path("evidenceId").asText());assertFalse(result.has("rawClose"));assertEquals(1,f.jdbc().queryForObject("select count(*) from alert_evidence_version",Integer.class));}

}
